cd /workspace && python3 - <<'PY'
import json, random, subprocess, sys, time
rng = random.Random(99)
U = 1 << 24
def part(k):
    if k <= 1: return [0, U]
    return [0] + sorted(rng.sample(range(1, U), k-1)) + [U]
runs = []
total_enq = 60000
TARGET_OPS = 100000
plans = [
    ('sff', 16, 8, 64, 'backlog'), ('wfq', 8, 4, 32, 'branch'),
    ('fifo', 4, 2, 16, 'sample'), ('sp', 2, 8, 40, 'pushout'),
    ('sff', 8, 2, 8, 'branch'), ('wfq', 4, 4, 24, 'backlog'),
    ('fifo', 16, 1, 48, 'sample'), ('sp', 1, 8, 12, 'pushout'),
]
for idx, (kind, M, L, R, mode) in enumerate(plans):
    flows = list(range(6))
    if kind == 'sp':
        policy = {'kind': 'sp', 'levels': [[f, rng.randrange(U)] for f in flows]}
    elif kind == 'wfq':
        policy = {'kind': 'wfq', 'weights': [[f, rng.randint(1, 1024)] for f in flows]}
    else:
        policy = {'kind': kind}
    ev = []
    nid = idx * 100000
    ops = 0
    budget = TARGET_OPS // len(plans)
    while ops < budget and total_enq > 0:
        pick = rng.random()
        if pick < 0.55:
            ev.append(['enqueue', nid, rng.choice(flows), rng.randint(1, 9000), rng.randrange(U)])
            nid += 1; ops += 1; total_enq -= 1
        elif pick < 0.80:
            n = rng.randint(1, 4); ev.append(['dequeue', n]); ops += n
        elif pick < 0.85:
            ev.append(['sample']); ops += 1
        elif pick < 0.90:
            ev.append(['cancel', rng.randrange(nid)]); ops += 1
        elif pick < 0.94:
            ev.append(['inspect', rng.randrange(nid)]); ops += 1
        elif pick < 0.97:
            ev.append(['save', rng.randrange(4)]); ops += 1
        else:
            ev.append(['restore', rng.randrange(nid % 4)]); ops += 1
    if mode == 'branch':
        for _ in range(200):
            ev.append(['restore', 0])
            for _ in range(5):
                ev.append(['enqueue', nid, 0, 100, rng.randrange(U)]); nid += 1
    runs.append({'banks': M, 'load_balancers': L,
                 'fifo_bytes': rng.choice([12000, 10 ** 7, 10 ** 9]),
                 'pifo_bytes': rng.choice([9000, 10 ** 6, 10 ** 9]),
                 'refill_batch': rng.choice([1, 8, 32]),
                 'sample_period': rng.choice([10, 100, 5000]),
                 'borders': part(R), 'policy': policy, 'events': ev})
data = json.dumps({'runs': runs}).encode()
print('input bytes', len(data), 'runs', len(runs), 'events', sum(len(r['events']) for r in runs))
open('/workspace/tmp/mega.json','wb').write(data)
start=time.time()
proc = subprocess.run([sys.executable,'-I','-B','submission/cli.py'], input=data, capture_output=True)
print('rc', proc.returncode, 'wall %.2f' % (time.time()-start), 'out', len(proc.stdout))
if proc.returncode: print(proc.stderr.decode()[-3000:])
PY
